read_file(char *path, char *buf, size_t max)
{
    int fd = open(path, O_RDONLY);
    if (fd <= 0)
    {
        err(1, "cannot open file");
    }
    size_t n = read(fd, buf, max);
    if (fd <= 0)
    {
        err(1, "cannot read file");
    }
    close(fd);
