void set_syscall_regs(uc_engine *uc)
{
    uc_reg_write(uc, UC_X86_REG_RAX, &allregs[13]);
    uc_reg_write(uc, UC_X86_REG_RDI, &allregs[8]);
    uc_reg_write(uc, UC_X86_REG_RSI, &allregs[9]);
