    {
        int c = read(0, buf, 1);
        if (c <= 0)
        {
            err(1, "error reading input");
        }
        return buf[0];
    }

    return -1;
}

static void handle_kernel_out(uc_engine *uc, uint32_t port, int size, uint32_t value, void *user_data)
